# Biological sequences used below are the native components associated with the selected records.
flag='DYKDDDDK'
clover='VSKGEELFTGVVPILVELDGDVNGHKFSVRGEGEGDATNGKLTLKFICTTGKLPVPWPTLVTTFGYGVACFSRYPDHMKQHDFFKSAMPEGYVQERTISFKDDGTYKTRAEVKFEGDTLVNRIELKGIDFKEDGNILGHKLEYNFNSHNVYITADKQKNGIKANFKIRHNVEDGSVQLADHYQQNTPIGDGPVLLPDNHYLSHQSALSKDPNEKRDHMVLLEFVTAAGITHGMDELYK'
dhfr='ISLIAALAVDRVIGMENAMPWNLPADLAWFKRNTLNKPVIMGRHTWESIGRPLPGRKNIILSSQPGTDDRVTWVKSVDEAIAACGDVPEIMVIGGGRVYEQFLPKAQKLYLTHIDAEVEGDTHFPDYEPDDWESVFSEFHDADAQNSHSYCFEILERR'
mcherry='VSKGEEDNMAIIKEFMRFKVHMEGSVNGHEFEIEGEGEGRPYEGTQTAKLKVTKGGPLPFAWDILSPQFMYGSKAYVKHPADIPDYLKLSFPEGFKWERVMNFEDGGVVTVTQDSSLQDGEFIYKVKLRGTNFPSDGPVMQKKTMGWEASSERMYPEDGALKGEIKQRLKLKDGGHYDAEVKTTYKAKKPVQLPGAYNVNIKLDITSHNEDYTIVEQYERAEGRHSTGGMDELYK'
snap='GPGSDKDCEMKRTTLDSPLGKLELSGCEQGLHEIIFLGKGTSAADAVEVPAPAAVLGGPEPLMQATAWLNAYFHQPEAIEEFPVPALHHPVFQQESFTRQVLWKLLKVVKFGEVISYSHLAALAGNPAATAAVKTALSGNPVPILIPCHRVVQGDLDVGGYEGGLAVKEWLLAHEGHRLGKR'
aa=flag+'GSGSG'+clover+'GSGSG'+dhfr+'GSGSG'+mcherry+'GSGSG'+snap
print('aa len',len(aa))
codons={
'A':['GCT','GCC','GCA','GCG'],'C':['TGT','TGC'],'D':['GAT','GAC'],'E':['GAA','GAG'],'F':['TTT','TTC'],'G':['GGT','GGC','GGA','GGG'],'H':['CAT','CAC'],'I':['ATT','ATC','ATA'],'K':['AAA','AAG'],'L':['TTA','TTG','CTT','CTC','CTA','CTG'],'M':['ATG'],'N':['AAT','AAC'],'P':['CCT','CCC','CCA','CCG'],'Q':['CAA','CAG'],'R':['CGT','CGC','CGA','CGG','AGA','AGG'],'S':['TCT','TCC','TCA','TCG','AGT','AGC'],'T':['ACT','ACC','ACA','ACG'],'V':['GTT','GTC','GTA','GTG'],'W':['TGG'],'Y':['TAT','TAC']}
for x in aa:
 if x not in codons: raise ValueError(x)

def gc(s): return sum(c in 'GC' for c in s)
def score(d):
  vals=[gc(d[i:i+50]) for i in range(len(d)-49)]
  bad=sum(max(0,15-v, v-35)**2 for v in vals)
  # small centering term, but prioritize valid bounds
  spread=sum((v-25)**2 for v in vals)/len(vals)
  return bad*100+spread, min(vals), max(vals), sum(v<15 or v>35 for v in vals)

def make_initial(mode):
  out=[]
  for x in aa:
    opts=codons[x]
    if mode=='balanced':
      # choose codon closest to 50% GC
      best=min(opts,key=lambda c:(abs(gc(c)-1.5),random.random()))
    elif mode=='low': best=min(opts,key=lambda c:(gc(c),random.random()))
    elif mode=='high': best=max(opts,key=lambda c:(gc(c),random.random()))
    else: best=random.choice(opts)
    out.append(best)
  return out

def evaluate(cods):
  return score(''.join(cods))

best=None
for restart in range(20):
  mode=['balanced','random','low','high'][restart%4]
  cod=make_initial(mode)
  cur=evaluate(cod)[0]
  for it in range(300000):
    j=random.randrange(len(cod)); old=cod[j]; opts=codons[aa[j]]
    if len(opts)==1: continue
    new=random.choice(opts)
    if new==old: continue
    cod[j]=new
    ns=evaluate(cod)[0]
    temp=2.0*(1-it/300000)+0.02
    if ns<=cur or random.random()<math.exp((cur-ns)/temp): cur=ns
    else: cod[j]=old
    if cur==0: break
  s=''.join(cod); stats=score(s)
  if best is None or stats[0]<best[0]: best=(stats[0],stats,cod[:])
  print('restart',restart,'stats',stats,'best',best[1])
  if stats[1]>=15 and stats[2]<=35: break
s=''.join(best[2]); stats=score(s)
print('FINAL',stats,'nt',len(s))
print('SEQ='+s)
print('TRANSLATION_OK', ''.join(next(k for k,v in codons.items() if c in v) for c in best[2])==aa)
